"""Recalculate the complete frame-guard study from raw JSONL, without importing its driver."""
import argparse
import csv
import hashlib
import itertools
import json
from pathlib import Path
import statistics


ARMS = ('original-off', 'original-dense', 'candidate-dense')
METRICS = ('totalNs', 'allThreadAllocatedBytes', 'callerThreadAllocatedBytes', 'prepareNs',
           'evaluateNs', 'firstRowAfterEvaluateNs', 'consumeNs', 'closeNs', 'ledgerPeakBytes')


def require(condition, detail):
    if not condition:
        raise ValueError(detail)


def read_json(path):
    return json.loads(path.read_text())


def write_new(path, data):
    with path.open('x') as out:
        json.dump(data, out, indent=2, sort_keys=True)
        out.write('\n')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('study', type=Path)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    study = args.study.resolve(strict=True)
    protocol = read_json(study / 'used-protocol.json')
    require(protocol['balancedOrders'] == [list(x) for x in itertools.permutations(ARMS)],
            'The raw study does not use all six prespecified orders')
    require(protocol['warmup'] == 8 and protocol['iterations'] == 5, 'Changed sampling design')
    preservation = read_json(study / 'post-run-preservation.json')
    require(preservation['identityFilesUnchanged'] and all(preservation['runtimeIdentitiesUnchanged'].values()),
            'Runtime or protocol identity changed')
    driver_summary = read_json(study / 'summary.json')
    require(driver_summary['complete'] and driver_summary['completedJvms'] == 18 and not driver_summary['errors'],
            'Incomplete study has no accepted comparison estimates')
    forks, raw_rows, route_signatures = [], [], set()
    expected_folders = set()
    for round_index, order in enumerate(itertools.permutations(ARMS)):
        for position, arm in enumerate(order):
            folder = study / f'round-{round_index:02d}-{position:02d}-{arm}'
            expected_folders.add(folder.name)
            process = read_json(folder / 'process-result.json')
            require(process['exitCode'] == 0 and process['failure'] is None, 'Unsuccessful fork ' + folder.name)
            records = [json.loads(x) for x in (folder / 'samples.jsonl').read_text().splitlines() if x.strip()]
            require(len(records) == 14 and records[0]['type'] == 'metadata', 'Wrong raw record count')
            meta, samples = records[0], records[1:]
            mode = 'off' if arm == 'original-off' else 'dense'
            require(meta['arm'] == arm and meta['nativeEvaluation'] and meta['directAdjacency']
                    and meta['directAdjacencyMode'] == 'PREFER'
                    and meta['systemProperties']['rdf4j.lmdb.resultCoordinateTransport'] == mode
                    and meta['querySha256'] == '9cffa2dc37bbb1e2743442b228d5ab9a41115bf7c4a6667506231fbda3bfc301'
                    and meta['canonicalGraphSha256'] == 'cf637a7e80dbd9468d7e8b04116da072f726038282dfab15380c267c8cc82e9b',
                    'Input, arm or configuration mismatch')
            for index, sample in enumerate(samples):
                require(sample['iteration'] == index - 8
                        and sample['stage'] == ('warmup' if index < 8 else 'measurement'), 'Wrong chronology')
                require(sample['valid'] and sample['complete'] and sample['ledgerReleased']
                        and sample['rows'] == 1_152_000 and sample['checksum'] == '3123987218479850048'
                        and sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0,
                        'Result or lifetime mismatch')
                counters, adjacency = sample['counters'], sample['adjacency']
                require(sample['auto'] and sample['autoRequested'] and sample['successfulSelections']
                        and all('forced' not in x['mode'] for x in sample['successfulSelections'])
                        and counters['semanticNativeCompiles'] == counters['irOpened'] == 1
                        and counters['irRows'] == 1_152_000, 'Wrong actual AUTO/native route')
                require(adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE'
                        and adjacency['lookupHits'] > 0
                        and adjacency['currentRevisionBefore'] == adjacency['appliedRevisionBefore']
                        == adjacency['currentRevisionAfter'] == adjacency['appliedRevisionAfter']
                        == meta['adjacencySetup']['currentDataRevision'], 'Adjacency evidence differs')
                admission = counters['coordinateAdmissions']
                require(admission['opened'] == (0 if mode == 'off' else 1)
                        and admission['initialAdmissionRefused'] == admission['growthAdmissionRefused'] == 0,
                        'Wrong coordinate participation')
                require(all(sample[k] >= 0 for k in METRICS), 'Negative measurement')
                if index >= 8:
                    require(counters['compiledBinds'] == 1 and counters['interpretedBinds']
                            == counters['aggregateCompiledBinds'] == counters['aggregateInterpretedBinds'] == 0,
                            'Measured query did not use compiled-only IR')
                    route_signatures.add(json.dumps(sample['successfulSelections'], sort_keys=True))
                raw_rows.append({'round': round_index, 'position': position, 'arm': arm,
                    'iteration': sample['iteration'], 'stage': sample['stage'],
                    **{k: sample[k] for k in METRICS}, 'lazyValueCalls': counters['lazyValueCalls'],
                    'adjacencyLookupHits': adjacency['lookupHits'], 'rows': sample['rows'],
                    'checksum': sample['checksum'], 'ledgerAfterBytes': sample['ledgerAfterBytes']})
            audit = read_json(folder / 'root-host-audit.json')
            require(audit['harnessReturned'] and audit['harnessFailureClass'] is None
                    and audit['hostedGenericTotal'] == 0 and audit['semanticNativeCompilesTotal'] == 13,
                    'Root audit mismatch')
            measured = samples[8:]
            forks.append({'round': round_index, 'position': position, 'arm': arm,
                'medians': {k: statistics.median(s[k] for s in measured) for k in METRICS},
                'lazyValueCalls': sorted({s['counters']['lazyValueCalls'] for s in measured}),
                'adjacencyLookupHits': sorted({s['adjacency']['lookupHits'] for s in measured}),
                'firstQuery': {k: samples[0][k] for k in METRICS}})
    require(expected_folders == {p.name for p in study.glob('round-*') if p.is_dir()}, 'Unexpected or missing forks')
    require(len(route_signatures) == 1, 'Measured AUTO selections differ')
    indexed = {(x['round'], x['arm']): x for x in forks}
    comparisons = []
    for a, b in (('candidate-dense', 'original-dense'), ('candidate-dense', 'original-off'),
                 ('original-dense', 'original-off')):
        ratios = {k: [indexed[r, a]['medians'][k] / indexed[r, b]['medians'][k]
                      if indexed[r, b]['medians'][k] else None for r in range(6)] for k in METRICS}
        medians = {k: statistics.median([v for v in values if v is not None])
                   if any(v is not None for v in values) else None for k, values in ratios.items()}
        reported = next(c for c in driver_summary['comparisons'] if c['candidate'] == a and c['comparator'] == b)
        require(medians == reported['medianRatios'], 'Independent ratios disagree with driver summary')
        comparisons.append({'candidate': a, 'comparator': b, 'ratiosByRound': ratios,
            'medianRatios': medians,
            'latencyRatioRange': [min(ratios['totalNs']), max(ratios['totalNs'])],
            'allSixLatencyRatiosBelowOne': all(v < 1 for v in ratios['totalNs'])})
    arms = {}
    for arm in ARMS:
        fs = [x for x in forks if x['arm'] == arm]
        arms[arm] = {'medianOfForkMedians': {k: statistics.median(f['medians'][k] for f in fs) for k in METRICS},
            'forkMedianRanges': {k: [min(f['medians'][k] for f in fs), max(f['medians'][k] for f in fs)] for k in METRICS},
            'firstQueryMedian': {k: statistics.median(f['firstQuery'][k] for f in fs) for k in METRICS},
            'lazyValueCallValues': sorted({v for f in fs for v in f['lazyValueCalls']}),
            'adjacencyLookupHitValues': sorted({v for f in fs for v in f['adjacencyLookupHits']})}
    result = {'valid': True, 'freshJvms': 18, 'queries': len(raw_rows), 'warmupQueries': 144,
        'measuredQueries': 90, 'allResultsAndLedgersValid': True, 'measuredRouteSelectionsEqual': True,
        'source': 'Independent recalculation from each fork samples.jsonl and process/root records; no driver imported.',
        'statistic': 'Arm: median of six five-query JVM medians. Ratios: median of six within-round ratios. Ranges are observed extrema, not confidence intervals.',
        'arms': arms, 'comparisons': comparisons, 'forks': forks,
        'protocolSha256': hashlib.sha256((study / 'used-protocol.json').read_bytes()).hexdigest(),
        'analysisScriptSha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}
    args.output.mkdir(parents=True, exist_ok=False)
    write_new(args.output / 'independent-results.json', result)
    with (args.output / 'all-queries.csv').open('x', newline='') as out:
        writer = csv.DictWriter(out, fieldnames=list(raw_rows[0]))
        writer.writeheader()
        writer.writerows(raw_rows)
    print(json.dumps({k: result[k] for k in ('valid', 'freshJvms', 'queries', 'measuredQueries', 'arms', 'comparisons')}, indent=2))


if __name__ == '__main__':
    main()
